function validate([lo, hi, k]) {
  if (![lo, hi, k].every(Number.isInteger)) return 'lo, hi and k are integers.';
  if (lo < 1 || hi > 1000 || lo > hi) return 'Need 1 <= lo <= hi <= 1000.';
  if (k < 1 || k > hi - lo + 1) return 'k is between 1 and the number of integers from lo to hi.';
  return null;
}

