function getKth(lo, hi, k) {
  const memo = new Map([[1, 0]]);
  const ranked = [];
  for (let x = lo; x <= hi; x++) {
    const path = [];
    let value = x;
    while (!memo.has(value)) {
      path.push(value);
      value = value % 2 === 0 ? value / 2 : 3 * value + 1;
    }
    let steps = memo.get(value);
    while (path.length > 0) {
      steps++;
      memo.set(path.pop(), steps);
    }
    ranked.push([memo.get(x), x]);
  }
  ranked.sort((a, b) => a[0] - b[0] || a[1] - b[1]);
  return ranked[k - 1][1];
}

