function getKth(lo, hi, k) {
  // Count the steps directly every time, then pick the smallest remaining integer k times.
  const power = x => { let count = 0; while (x !== 1) { x = x % 2 === 1 ? 3 * x + 1 : x / 2; count++; } return count; };
  const remaining = [];
  for (let x = lo; x <= hi; x++) remaining.push(x);
  let chosen = null;
  for (let round = 0; round < k; round++) {
    let best = 0;
    for (let i = 1; i < remaining.length; i++) {
      const a = power(remaining[i]), b = power(remaining[best]);
      if (a < b || (a === b && remaining[i] < remaining[best])) best = i;
    }
    chosen = remaining.splice(best, 1)[0];
  }
  return chosen;
}

