function generate(rand, size) {
  const pick = n => Math.floor(rand() * n);
  let lo, hi;
  if (size === 'large') {
    lo = 1 + pick(60);
    hi = 1000 - pick(60);
  } else {
    lo = rand() < 0.3 ? 1 + pick(5) : 1 + pick(990);
    hi = Math.min(1000, lo + pick(15));
  }
  const k = 1 + pick(hi - lo + 1);
  return [lo, hi, k];
}
